head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf30110";
scwin.tbl_team = null;
scwin.calendar = null;
scwin.list = null;
scwin.tbl_list = null;
scwin.gform_cd = "70932,70933,70934";
scwin.gadm_tp_cd = "21,22";
scwin.pathname = undefined;
scwin.qry = undefined;
scwin.dep_cd = undefined;
scwin.jsteam = undefined;
scwin.gParamObj = undefined;
scwin.options = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — param.session_depcd, today, param.INIT_READ

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_first", fn: function(){ return ((dma_s.get("first") ?? (() => { throw new Error("unresolved:" + "s.first"); })())); } }, { id: "c_if_85", fn: function(){ return ((dlt_cmbDepCd.getCellData(0, "key") ?? (() => { throw new Error("unresolved:" + "DepCd.key"); })()) === (dma_pageContext.get("sessionDepcd") ?? "")); } }, { id: "if_first", fn: function(){ return ('2B' === String((dma_pageContext.get("sessionDepcd") ?? "")).substring(0, 2)); } }, { id: "c_if_85", fn: function(){ return ('2B' === String((dma_pageContext.get("sessionDepcd") ?? "")).substring(0, 2)); } }, { id: "c_otherwise_87", fn: function(){ return (!(('2B' === String((dma_pageContext.get("sessionDepcd") ?? "")).substring(0, 2)))); } }, { id: "c_when_147", fn: function(){ return (((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())+1) % 7 === 0); } }, { id: "c_when_149", fn: function(){ return (((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())+1) % 7 === 1); } }, { id: "c_otherwise_151", fn: function(){ return (!((((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())+1) % 7 === 0) || (((dma_status.get("index") ?? (() => { throw new Error("unresolved:" + "status.index"); })())+1) % 7 === 1))); } }, { id: "if_index", fn: function(){ return ((dma_rowInfostatus.get("index") ?? (() => { throw new Error("unresolved:" + "rowInfostatus.index"); })()) === 0); } }, { id: "c_when_164", fn: function(){ return ((dlt_rowCalendarValue.getCellData(0, "disclsSchdlActStatCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlActStatCd"); })()) === "0"); } }, { id: "c_when_166", fn: function(){ return ((dlt_rowCalendarValue.getCellData(0, "disclsSchdlActStatCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlActStatCd"); })()) === "1"); } }, { id: "c_when_168", fn: function(){ return ((dlt_rowCalendarValue.getCellData(0, "disclsSchdlActStatCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlActStatCd"); })()) === "2"); } }, { id: "c_when_170", fn: function(){ return ((dlt_rowCalendarValue.getCellData(0, "disclsSchdlActStatCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlActStatCd"); })()) === "3"); } }, { id: "c_otherwise_172", fn: function(){ return (!(((dlt_rowCalendarValue.getCellData(0, "disclsSchdlActStatCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlActStatCd"); })()) === "0") || ((dlt_rowCalendarValue.getCellData(0, "disclsSchdlActStatCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlActStatCd"); })()) === "1") || ((dlt_rowCalendarValue.getCellData(0, "disclsSchdlActStatCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlActStatCd"); })()) === "2") || ((dlt_rowCalendarValue.getCellData(0, "disclsSchdlActStatCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlActStatCd"); })()) === "3"))); } }, { id: "c_when_177", fn: function(){ return ((dlt_rowCalendarValue.getCellData(0, "admDeadlineDd") ?? (() => { throw new Error("unresolved:" + "rowInfo.admDeadlineDd"); })()) < (dma_pageContext.get("today") ?? "")); } }, { id: "c_when_179", fn: function(){ return ((dlt_rowCalendarValue.getCellData(0, "disclsSchdlActStatCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlActStatCd"); })()) === "0"); } }, { id: "c_when_181", fn: function(){ return ((dlt_rowCalendarValue.getCellData(0, "disclsSchdlActStatCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlActStatCd"); })()) === "1"); } }, { id: "c_when_183", fn: function(){ return ((dlt_rowCalendarValue.getCellData(0, "disclsSchdlActStatCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlActStatCd"); })()) === "2"); } }, { id: "c_when_185", fn: function(){ return ((dlt_rowCalendarValue.getCellData(0, "disclsSchdlActStatCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlActStatCd"); })()) === "3"); } }, { id: "c_otherwise_187", fn: function(){ return (!(((dlt_rowCalendarValue.getCellData(0, "admDeadlineDd") ?? (() => { throw new Error("unresolved:" + "rowInfo.admDeadlineDd"); })()) < (dma_pageContext.get("today") ?? "")) || ((dlt_rowCalendarValue.getCellData(0, "disclsSchdlActStatCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlActStatCd"); })()) === "0") || ((dlt_rowCalendarValue.getCellData(0, "disclsSchdlActStatCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlActStatCd"); })()) === "1") || ((dlt_rowCalendarValue.getCellData(0, "disclsSchdlActStatCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlActStatCd"); })()) === "2") || ((dlt_rowCalendarValue.getCellData(0, "disclsSchdlActStatCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlActStatCd"); })()) === "3"))); } }, { id: "if_schdlTpCd", fn: function(){ return ((dlt_rowCalendarValue.getCellData(0, "schdlTpCd") ?? (() => { throw new Error("unresolved:" + "rowInfo.schdlTpCd"); })()) === "5"); } }, { id: "if_disclsSchdlAdmContn", fn: function(){ return (!(String(((dlt_rowCalendarValue.getCellData(0, "disclsSchdlAdmContn") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlAdmContn"); })())) === null ? '' : ((dlt_rowCalendarValue.getCellData(0, "disclsSchdlAdmContn") ?? (() => { throw new Error("unresolved:" + "rowInfo.disclsSchdlAdmContn"); })()))).length === 0)); } }, { id: "if_disclsSchdlAdmContn", fn: function(){ return ((dma_pageContext.get("INIT_READ") ?? "") !== 'Y'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_80", entity: "dlt_cmbDepCd", countIds: [], cells: [{ childId: "option_84", fn: function (v, i) { return String(v("key")); } }, { childId: "__rc0", fn: function (v, i) { return String(v("value")); } }, { childId: "option_86", fn: function (v, i) { return String(v("key")); } }, { childId: "__rc1", fn: function (v, i) { return String(v("value")); } }, { childId: "option_88", fn: function (v, i) { return String(v("key")); } }, { childId: "__rc2", fn: function (v, i) { return String(v("value")); } }] },
        { genId: "c_foreach_92", entity: "dlt_cmbEmpNo", countIds: [], cells: [{ childId: "option_93", fn: function (v, i) { return String(v("value")) + "|" + String(v("value")); } }, { childId: "__rc3", fn: function (v, i) { return String(v("text")); } }] },
        { genId: "c_foreach_140", entity: "dlt_rowCalendarValue", countIds: [], cells: [{ childId: "__rc4", fn: function (v, i) { return String(String(v("admDeadlineDd")).substring(6, 8)); } }, { childId: "__rc5", fn: function (v, i) { return String(String(v("admDeadlineDd")).substring(6, 8)); } }, { childId: "__rc6", fn: function (v, i) { return String(String(v("admDeadlineDd")).substring(6, 8)); } }, { childId: "__rc7", fn: function (v, i) { return "\"), \"'\", \"\"), \"\\\"\", \" \"), \"\\\\\", \"\\\\ \") }' , '" + String(v("empNm")) + "', '" + String(v("disclsPublDdtm")) + "', '${ fn:replace(fn:replace(fn:replace(fn:replace(rowInfo.remk, CRLF, \""; } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_sessionDepcd", fn: function () { return String((dma_pageContext.get("sessionDepcd") ?? "")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.pathname =location.pathname; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30110' }); }

try { scwin.qry =location.search; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30110' }); }

try { scwin.dep_cd =$c.session.getUserInfo("depCd"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30110' }); }

try { scwin.jsteam =js_team; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30110' }); }

try { scwin.gParamObj =new Array(4); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30110' }); }

try { scwin.options =[]; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf30110' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.tbl_team = $c.util.getComponent('tbl_team');
        scwin.calendar = $c.util.getComponent('calendar');
        scwin.list = $c.util.getComponent('list');
        scwin.tbl_list = $c.util.getComponent('tbl_list');
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_fillGen();
        await scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf30110.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf30110.btn_Search_onclick' }); }
};

/**
 * @method
 * @name btn_Memo_onclick
 * @description 「메모입력」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Memo_onclick = function(e){
    try {
        scwin.memo()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30110.btn_Memo_onclick' }); }
};

/**
 * @method
 * @name btn_openSchdul_onclick
 * @description 「일정추출계산식」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_openSchdul_onclick = function(e){
    try {
        scwin.openSchdul()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30110.btn_openSchdul_onclick' }); }
};

/**
 * @method
 * @name btn_openMonthlyNoti_onclick
 * @description btn_openMonthlyNoti 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_openMonthlyNoti_onclick = function(e){
    try {
        scwin.openMonthlyNoti()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf30110.btn_openMonthlyNoti_onclick' }); }
};

/**
 * @method
 * @name btn_readSchedule_onclick
 * @description btn_readSchedule 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_readSchedule_onclick = async function(e){
    try {
        await scwin.readSchedule('R','' + dlt_rowCalendarValue.getCellData(0, "disclsSchdlAdmDd") + '','' + dlt_rowCalendarValue.getCellData(0, "byddSeq") + '','' + dlt_rowCalendarValue.getCellData(0, "integUsrId") + '','' + dlt_rowCalendarValue.getCellData(0, "schdlTpCd") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf30110.btn_readSchedule_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/DisclosureSchedule.do",
        ref: "dma_SearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/DisclosureSchedule.do",
        ref: "dma_loadListReq",
        target: "dlt_CalInfo=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name swich_div
 * @description swich div 처리
 * @param {*} id id
 * @returns {void}
 * @hidden N
 */
scwin.swich_div = function (id) {
    if (id === scwin.calendar) {
        scwin.tbl_list.setStyle("display", "none");
        tbl_calendar.style.display = "";
        scwin.calendar.className = "tab_on";
        scwin.list.className = "tab_off";
    } else {
        if (id === scwin.list) {
            scwin.tbl_list.setStyle("display", "");
            tbl_calendar.style.display = "none";
            scwin.calendar.className = "tab_off";
            scwin.list.className = "tab_on";
        }
    }
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    if ($c.util.getComponent('slc_YYYY').getValue() === "") {
        await $c.win.alert("[검색 년]을 선택하세요.");
        $c.util.getComponent("slc_YYYY").focus();
        return;
    }
    if ($c.util.getComponent('slc_MM').getValue() === "") {
        await $c.win.alert("[검색 월]을 선택하세요.");
        $c.util.getComponent("slc_MM").focus();
        return;
    }
    $c.util.getComponent('dma_SearchReq').set('method', "listDisclsScheduleKos");
    await scwin.tx_fn_Search();
};

/**
 * @method
 * @name dis_msg
 * @description dis msg 처리
 * @param {*} tmp1 tmp1
 * @param {*} tmp2 tmp2
 * @param {*} tmp3 tmp3
 * @param {*} tmp4 tmp4
 * @param {*} pub_ddtm pub_ddtm
 * @param {*} remk remk
 * @returns {void}
 * @hidden N
 */
scwin.dis_msg = function (tmp1, tmp2, tmp3, tmp4, pub_ddtm, remk) {
    let str = "";
    const content = "";
    let left_1 = "";
    let top_1 = "";
    const mousey = "";
    left_1 = event.clientX + document.body.scrollLeft;
    top_1 = event.clientY + document.body.scrollTop;
    str += "<table width=\"290\" height=\"16\" cellpadding=\"4\" cellspacing=\"1\" bgcolor=\"#CC9D74\" border=\"0\">";
    str += "  <tr align=\"center\">";
    str += "    <td width=\"90\"  bgcolor=\"#F4E1C1\">회사명(종목명)</td>";
