    ($c.util.getComponent('btn_memo') && $c.util.getComponent('btn_memo').hide ? $c.util.getComponent('btn_memo').hide() : console.warn('[sdd] hide 대상 미해결: ' + 'btn_memo'));
    if (scwin.dep_cd.substring(0, 2) !== "34") {
        ($c.util.getComponent('monthlyNoti') && $c.util.getComponent('monthlyNoti').hide ? $c.util.getComponent('monthlyNoti').hide() : console.warn('[sdd] hide 대상 미해결: ' + 'monthlyNoti'));
