/**
 * @method
 * @name insertOption
 * @description insert Option 처리
 * @param {*} selectObject selectObject
 * @param {*} value value
 * @param {*} text text
 * @returns {void}
 * @hidden N
 */
scwin.insertOption = function (selectObject, value, text) {
    if (selectObject === null) {
        return false;
    }
    for (i = 0; i < selectObject.length; i++) {
        if (selectObject.options[i].value === value) {
            return;
        }
    }
    const e1 = document.createElement("OPTION");
    e1.text = text;
    e1.value = value;
    selectObject.options.add(e1);
};

/**
 * @method
 * @name doChange_step1
 * @description do Change step1 처리
 * @returns {void}
 * @hidden N
 */
scwin.doChange_step1 = function () {
    const theForm = (document.DsclScheduleForm || { elements: [] });
    const sDEPCD = $c.util.getComponent("dma_SearchReq").get("DEPCD");
    for (let i = theForm.EMPNO.length - 1; i >= 0; i--) {
        theForm.EMPNO.removeChild(theForm.EMPNO[i]);
    }
    scwin.insertOption(theForm.EMPNO, "", "전체");
    if (sDEPCD === "") {
        for (let i = 1; i < scwin.options.length; i++) {
            let value = scwin.options[i].split("|")[1];
            let text = scwin.options[i].split("|")[2];
            scwin.insertOption(theForm.EMPNO, value, text);
        }
    } else {
        for (let i = 1; i < scwin.options.length; i++) {
            const keyDEPCD = scwin.options[i].split("|")[0];
            if (keyDEPCD === sDEPCD) {
                value = scwin.options[i].split("|")[1];
                text = scwin.options[i].split("|")[2];
                scwin.insertOption(theForm.EMPNO, value, text);
            }
        }
    }
};

