 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSchedule = async function (cmd, discls_schdl_adm_dd, bydd_seq, integ_usr_id, schdl_tp_cd) {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.FrameID, $c.frame.Provider
    if (await scwin.setParam(cmd, discls_schdl_adm_dd, bydd_seq, integ_usr_id)) {
        if (schdl_tp_cd === '5') {
            let url = "/dsclmgt/ULDSTF30012.gfm?src=JSP";
        } else {
            if (schdl_tp_cd === '6') {
                url = "/dsclmgt/ULDSTF30012.gfm?src=JSP";
            } else {
                url = "/child01/child01.xml?src=JSP";
            }
        }
        url += "&cmd=" + cmd;
        url += "&discls_schdl_adm_dd=" + discls_schdl_adm_dd;
        url += "&bydd_seq=" + bydd_seq;
        url += "&integ_usr_id=" + integ_usr_id;
        url += "&frameid=" + $c.frame.FrameID;
        $c.frame.Provider("../../").GWinOpen("child01", url, "일정조회", 20, 10, 10, 20, "");
    }
};

